export function waveform(t,{frequency=1000,vpp=2,offset=0,shape='sine',r=1000,c=100e-9,circuit='lowpass'}){
 const w=2*Math.PI*frequency,tau=r*c;let a=offset,b=circuit==='highpass'?0:offset;
 const count=shape==='sine'?1:35;
 for(let n=1;n<=count;n++){let k=0;if(shape==='sine')k=1;else if(shape==='square'&&n%2)k=4/(Math.PI*n);else if(shape==='triangle'&&n%2)k=8*Math.pow(-1,(n-1)/2)/(Math.PI*Math.PI*n*n);else if(shape==='saw')k=2*Math.pow(-1,n+1)/(Math.PI*n);if(!k)continue;const x=n*w*t,wt=n*w*tau,mag=circuit==='direct'?1:circuit==='lowpass'?1/Math.sqrt(1+wt*wt):wt/Math.sqrt(1+wt*wt),phase=circuit==='direct'?0:circuit==='lowpass'?-Math.atan(wt):Math.PI/2-Math.atan(wt);a+=vpp/2*k*Math.sin(x);b+=vpp/2*k*mag*Math.sin(x+phase);}
 return [a,b];
}
export function scopeMetrics(p){let lo=[Infinity,Infinity],hi=[-Infinity,-Infinity];for(let i=0;i<1024;i++){const y=waveform(i/(1024*p.frequency),p);for(let ch=0;ch<2;ch++){lo[ch]=Math.min(lo[ch],y[ch]);hi[ch]=Math.max(hi[ch],y[ch]);}}const x=2*Math.PI*p.frequency*p.r*p.c;return {vpp:hi.map((v,i)=>v-lo[i]),fc:1/(2*Math.PI*p.r*p.c),gain:p.circuit==='direct'?1:p.circuit==='lowpass'?1/Math.sqrt(1+x*x):x/Math.sqrt(1+x*x),phase:p.circuit==='direct'?0:(p.circuit==='lowpass'?-Math.atan(x):Math.PI/2-Math.atan(x))*180/Math.PI};}
export function signalMeter(p,red='out',black='gnd',mode='dc'){const samples=Array.from({length:1024},(_,i)=>{const a=waveform(i/(1024*p.frequency),p),nodes={in:a[0],out:a[1],gnd:0};return nodes[red]-nodes[black];});const mean=samples.reduce((a,b)=>a+b,0)/samples.length;return mode==='dc'?mean:mode==='ac'?Math.sqrt(samples.reduce((a,b)=>a+(b-mean)**2,0)/samples.length):Math.max(...samples)-Math.min(...samples);}
export function mountScope(storage){const $=id=>document.getElementById(id);let running=true,phase=0,task=0,passed=[];try{passed=JSON.parse(storage.getItem('circuitlab-scope-v4')||'[]');if(!Array.isArray(passed))passed=[];}catch{}
 const meter=document.createElement('section');meter.className='signalMeterInline';meter.innerHTML='<div><span>MULTÍMETRO DEL MISMO CIRCUITO</span><strong id="signalMeterValue">—</strong><small>Comparte IN, OUT y GND con el generador y el osciloscopio.</small></div><label>Función<select id="signalMeterMode"><option value="dc">V DC · media</option><option value="ac">V AC RMS</option><option value="vpp">Vpp · cálculo</option></select></label><label>Roja<select id="signalMeterRed"><option value="out">OUT</option><option value="in">IN</option><option value="gnd">GND</option></select></label><label>Negra<select id="signalMeterBlack"><option value="gnd">GND</option><option value="in">IN</option><option value="out">OUT</option></select></label>';document.getElementById('scopePage').prepend(meter);
 const tasks=[{name:'Encuadra una señal',text:'Selecciona seno, 1 kHz y 2 Vpp. Ajusta tiempo para ver entre 2 y 5 períodos y CH1 para que quepan los 2 Vpp. Activa disparo ascendente.',check:p=>p.shape==='sine'&&p.frequency===1000&&p.vpp===2&&p.trigger==='rise'&&p.time*p.frequency>=2&&p.time*p.frequency<=5&&p.scale1*8>=p.vpp},
 {name:'Encuentra la frecuencia de corte',text:'Elige RC paso bajo, R = 1 kΩ, C = 100 nF y seno. Calcula fc = 1/(2πRC), ajusta el generador a ±5 % de esa frecuencia y observa CH2 ≈ 70,7 % de CH1.',check:p=>p.shape==='sine'&&p.circuit==='lowpass'&&p.r===1000&&Math.abs(p.c-100e-9)<1e-15&&Math.abs(p.frequency-1/(2*Math.PI*p.r*p.c))/(1/(2*Math.PI*p.r*p.c))<.05},
 {name:'Observa carga y descarga',text:'Selecciona cuadrada de 100 Hz, RC paso bajo, R = 1 kΩ y C = 1 µF. Muestra de 2 a 5 períodos: la salida se aproxima exponencialmente a cada nivel.',check:p=>p.shape==='square'&&p.circuit==='lowpass'&&p.frequency===100&&p.r===1000&&Math.abs(p.c-1e-6)<1e-14&&p.time*p.frequency>=2&&p.time*p.frequency<=5},
 {name:'Separa alterna y continua',text:'Selecciona seno de 1 kHz, 2 Vpp, offset +2 V y RC paso alto. CH1 está centrado en 2 V; CH2, en 0 V. Mantén acoplamiento DC: el condensador del circuito elimina la continua.',check:p=>p.shape==='sine'&&p.circuit==='highpass'&&p.frequency===1000&&p.vpp===2&&p.offset===2}];
 const number=(id,min,max,fallback)=>{let n=Number($(id).value);if(!Number.isFinite(n))n=fallback;return Math.max(min,Math.min(max,n));};
 const params=()=>({shape:$('genShape').value,frequency:number('genFrequency',1,100000,1000),vpp:number('genVpp',.1,10,2),offset:number('genOffset',-5,5,0),r:number('scopeR',100,100000,1000),c:number('scopeC',1,10000,100)*1e-9,circuit:$('scopeCircuit').value,time:number('scopeTime',.0001,1000,.2)*.01,scale1:Number($('scopeScale1').value)||1,scale2:Number($('scopeScale2').value)||1,trigger:$('scopeTrigger').value,probe1:$('scopeProbe1')?.value||'in',probe2:$('scopeProbe2')?.value||'out',ground:$('scopeGround')?.value||'gnd'});
 function draw(){if(!running)return;const p=params(),m=scopeMetrics(p);const rawVpp=[...m.vpp];$('signalMeterValue').textContent=p.ground!=='gnd'?'Sin referencia':signalMeter(p,$('signalMeterRed').value,$('signalMeterBlack').value,$('signalMeterMode').value).toFixed(3)+' V';m.vpp=[p.probe1,p.probe2].map(v=>p.ground!=='gnd'||v==='off'?NaN:v==='gnd'?0:rawVpp[v==='in'?0:1]);let paths=['',''];const crowded=p.time*p.frequency>10;const t0=p.trigger==='free'?phase/p.frequency:p.trigger==='fall'?.5/p.frequency:0;
 for(let i=0;i<=1000&&!crowded;i++){const x=50+i*.8,raw=waveform(t0+(i/1000-.2)*p.time,p),y=[p.probe1,p.probe2].map(v=>p.ground!=='gnd'||v==='off'?NaN:v==='gnd'?0:raw[v==='in'?0:1]);for(let ch=0;ch<2;ch++)if(Number.isFinite(y[ch]))paths[ch]+=(i?'L':'M')+x.toFixed(2)+' '+(210-y[ch]*40/(ch?p.scale2:p.scale1)).toFixed(2);}
 let minor='';for(let i=0;i<=50;i++)if(i%5)minor+=`<path d="M${50+i*16} 50V370"/>`;for(let i=0;i<=40;i++)if(i%5)minor+=`<path d="M50 ${50+i*8}H850"/>`;let grid='';for(let i=0;i<=10;i++)grid+=`<path d="M${50+i*80} 50V370"/>`;for(let i=0;i<=8;i++)grid+=`<path d="M50 ${50+i*40}H850"/>`;
 $('scopeScreen').innerHTML=`<svg viewBox="0 0 900 410" role="img" aria-label="Osciloscopio: CH1 amarillo ${p.probe1}, CH2 azul ${p.probe2}"><defs><filter id="phosphor"><feGaussianBlur stdDeviation="1.4"/></filter><radialGradient id="screenShade"><stop stop-color="#0b2028"/><stop offset="1" stop-color="#040c13"/></radialGradient><clipPath id="scopeClip"><rect x="50" y="50" width="800" height="320"/></clipPath></defs><rect width="900" height="410" rx="12" fill="url(#screenShade)"/><g stroke="#213942" stroke-width=".5" opacity=".35">${minor}</g><g stroke="#38505a" stroke-width="1">${grid}</g><path d="M50 210H850M210 50V370" stroke="#738590" stroke-dasharray="4 6"/><g clip-path="url(#scopeClip)" fill="none" stroke-width="5" opacity=".35" filter="url(#phosphor)"><path d="${paths[0]}" stroke="#ffd45a"/><path d="${paths[1]}" stroke="#55c8ff"/></g><g clip-path="url(#scopeClip)" fill="none" stroke-width="1.6"><path d="${paths[0]}" stroke="#ffd45a"/><path d="${paths[1]}" stroke="#55c8ff"/></g><path d="M37 204L49 210L37 216Z" fill="#ffd45a"/><path d="M863 204L851 210L863 216Z" fill="#55c8ff"/><path d="M204 39L210 49L216 39Z" fill="#85edb8"/><g fill="#adbecb" font-family="monospace" font-size="12"><text x="50" y="28">CH1 ${p.scale1} V/div · CH2 ${p.scale2} V/div · ${(p.time*100).toPrecision(3)} ms/div</text><text x="50" y="396">0 V: eje central · 10 divisiones horizontales · 8 verticales · DC</text><text x="650" y="28">${p.trigger==='free'?'LIBRE':'TRIG · CH1 · OFFSET'}</text></g></svg>`;
 $('scopeReadout').innerHTML=`<div><span>FRECUENCIA / PERÍODO</span><b>${p.frequency.toLocaleString('es')} Hz / ${(1000/p.frequency).toPrecision(3)} ms</b></div><div><span>CH1 / CH2 · Vpp</span><b>${Number.isFinite(m.vpp[0])?m.vpp[0].toFixed(3):'—'} / ${Number.isFinite(m.vpp[1])?m.vpp[1].toFixed(3):'—'} V</b></div><div><span>CORTE RC</span><b>${m.fc.toFixed(1)} Hz</b></div><div><span>RESPUESTA A LA FUNDAMENTAL</span><b>${m.gain.toFixed(3)}× / ${m.phase.toFixed(1)}°</b></div>`;
 $('scopeWiring').textContent=(p.ground==='gnd'?'Referencia: GND. ':'Sin referencia. ')+`CH1: ${p.probe1} · CH2: ${p.probe2}. `+(p.circuit==='direct'?'Conexión directa: generador OUT = CH1 = CH2. Retorno común GND.':p.circuit==='lowpass'?'Paso bajo: OUT del generador → R → nodo CH2; C une CH2 a GND. CH1 mide la entrada antes de R. Ambas referencias a GND.':'Paso alto: OUT del generador → C → nodo CH2; R une CH2 a GND. CH1 mide antes de C. Ambas referencias a GND.');
 $('scopeClipping').textContent=p.ground!=='gnd'?'Conecta GND para establecer la referencia de las medidas.':p.probe1==='off'||p.probe2==='off'?'Hay una sonda desconectada; su canal no presenta lectura.':crowded?'Demasiados períodos para representar la señal con fidelidad. Reduce ms/div hasta mostrar como máximo 10 períodos o usa Autoajuste.':(m.vpp[0]/2+Math.abs(p.offset)>4*p.scale1||m.vpp[1]/2+(p.circuit==='highpass'?0:Math.abs(p.offset))>4*p.scale2)?'Parte de la señal queda fuera de pantalla: aumenta V/div.':'Las medidas se calculan sobre un período completo; no dependen de la porción visible.';
 }
 function taskUI(){$('scopeTaskTitle').textContent=`${task+1}. ${tasks[task].name}`;$('scopeTaskText').textContent=tasks[task].text;$('scopeTaskProgress').textContent=`${new Set(passed).size} / 4 prácticas comprobadas`;$('scopeTaskFeedback').textContent='';}
 for(const id of ['genShape','genFrequency','genVpp','genOffset','scopeR','scopeC','scopeCircuit','scopeTime','scopeScale1','scopeScale2','scopeTrigger'])$(id).oninput=draw;for(const id of ['scopeProbe1','scopeProbe2','scopeGround','signalMeterRed','signalMeterBlack','signalMeterMode'])if($(id))$(id).oninput=draw;
 $('scopeRun').onclick=()=>{running=!running;$('scopeRun').textContent=running?'Ⅱ Detener adquisición':'▶ Reanudar adquisición';$('scopeAcquisition').textContent=running?'ADQUISICIÓN ACTIVA':'DETENIDO · pantalla congelada';draw();};
 $('scopeAuto').onclick=()=>{const p=params();$('scopeTime').value=(300/p.frequency).toFixed(4);const extent=p.vpp/2+Math.abs(p.offset);const scale=[.1,.2,.5,1,2,5].find(v=>4*v>=extent*1.2)||5;$('scopeScale1').value=scale;$('scopeScale2').value=scale;draw();};
 $('scopeNext').onclick=()=>{task=(task+1)%tasks.length;taskUI();};$('scopePrev').onclick=()=>{task=(task+tasks.length-1)%tasks.length;taskUI();};$('scopeCheck').onclick=()=>{const ok=running&&tasks[task].check(params());if(ok){passed=[...new Set([...passed,task])];try{storage.setItem('circuitlab-scope-v4',JSON.stringify(passed));}catch{}}$('scopeTaskProgress').textContent=`${passed.length} / 4 prácticas comprobadas`;$('scopeTaskFeedback').textContent=ok?'✓ Configuración correcta. Explica qué cambia entre CH1 y CH2 y por qué.':'Revisa los valores, el circuito, la ventana de tiempo y que la adquisición esté activa.';};
 setInterval(()=>{if(!document.getElementById('scopePage').hidden&&running&&$('scopeTrigger').value==='free'){phase+=.08;draw();}},120);taskUI();draw();return {params,draw,isRunning:()=>running};
}
